<template><view class="page"><view class="title">贡献值与发单次数</view>
  <view v-for="item in items" :key="item.id" class="card"><view class="row"><text>{{ formatDate(item.periodEnd || item.createdAt) }}</text><text class="status">{{ item.newUserProtected?'新用户保护':'已结算' }}</text></view><view>贡献值：{{ item.scoreBefore }} → {{ item.scoreAfter }}</view><view>本周扣除：{{ item.totalDeduction }}</view><view>新一周发单次数：{{ item.newPostingQuota }}</view></view>
  <view v-if="!items.length&&!loading" class="empty">暂无每周结算记录</view></view></template>
<script setup>import { onReachBottom,onShow } from '@dcloudio/uni-app';import { ref } from 'vue';import { api } from '../../utils/request';const items=ref([]),page=ref(0),hasMore=ref(true),loading=ref(false);function formatDate(value){if(!value)return'';const date=value instanceof Date?value:new Date(value.$date??value);if(Number.isNaN(date.getTime()))return'';const pad=(number)=>String(number).padStart(2,'0');return`${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}`}async function load(reset=false){if(loading.value||(!reset&&!hasMore.value))return;if(reset){items.value=[];page.value=0;hasMore.value=true}loading.value=true;try{const r=await api.quotaRecords({page:page.value});items.value.push(...r.items);page.value++;hasMore.value=r.hasMore}finally{loading.value=false}}onShow(()=>load(true));onReachBottom(()=>load())</script>
